import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"14、【大有】 乾下離上","description":"溫公易說 - 14、【大有】 乾下離上","frontmatter":{"title":"14、【大有】 乾下離上","description":"溫公易說 - 14、【大有】 乾下離上"},"headers":[],"relativePath":"classics/wengong/015.md","filePath":"classics/wengong/015.md"}'),l={name:"classics/wengong/015.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_14、【大有】-乾下離上" tabindex="-1">14、【大有】 乾下離上 <a class="header-anchor" href="#_14、【大有】-乾下離上" aria-label="Permalink to “14、【大有】 乾下離上”">​</a></h1><h3 id="彖曰-大有-柔得尊位-大中而上下應之-曰大有。其德剛健而文明-應乎天而時行-是以元亨。" tabindex="-1">彖曰：大有，柔得尊位，大中而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。 <a class="header-anchor" href="#彖曰-大有-柔得尊位-大中而上下應之-曰大有。其德剛健而文明-應乎天而時行-是以元亨。" aria-label="Permalink to “彖曰：大有，柔得尊位，大中而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。”">​</a></h3><p>大有者，何？富有之謂也。天子富有天下，諸侯富有其國，大夫富有其家。非得大有之道，烏能得其下乎？然則大有何？以柔為主。夫為人上者，言而人莫敢違也，動而人莫敢逆也，故戒之在剛也。夫上之所以能有下者，得其心也。得其心者，能以恩信結之也。故大有以柔中為主也。柔而不明，則前有讒而弗見，後有賊而不知。明而不健，則知善而不能舉，知惡而不能去。二者皆亂亡之端也。明以燭之，健以決之，居不失中行，不失時，然後能保有其眾而元亨也。然則大有何以上明而下健？曰：明勝於健，則賞不失功，罰不失罪。健勝於明，則反之。此大有所以當明也。</p><h3 id="象曰-火在天上-大有。君子以遏惡揚善-順天休命。" tabindex="-1">象曰：火在天上，大有。君子以遏惡揚善，順天休命。 <a class="header-anchor" href="#象曰-火在天上-大有。君子以遏惡揚善-順天休命。" aria-label="Permalink to “象曰：火在天上，大有。君子以遏惡揚善，順天休命。”">​</a></h3><p>火在天上，明之至也。至明則善惡無所遺矣。善則舉之，惡則抑之。上之職也。明而能健，慶賞刑威，得其當然。後能保有四方，所以順天美命也。</p><h3 id="初九-無交害-匪咎-艱則無咎-象曰-大有初九-無交害也。" tabindex="-1">初九：無交害，匪咎，艱則無咎 象曰：大有初九，無交害也。 <a class="header-anchor" href="#初九-無交害-匪咎-艱則無咎-象曰-大有初九-無交害也。" aria-label="Permalink to “初九：無交害，匪咎，艱則無咎 象曰：大有初九，無交害也。”">​</a></h3><h3 id="九二-大車以載-有攸往-無咎-象曰-大車以載-積中不敗也。" tabindex="-1">九二：大車以載，有攸往，無咎 象曰：大車以載，積中不敗也。 <a class="header-anchor" href="#九二-大車以載-有攸往-無咎-象曰-大車以載-積中不敗也。" aria-label="Permalink to “九二：大車以載，有攸往，無咎 象曰：大車以載，積中不敗也。”">​</a></h3><h3 id="九三-公用亨於天子-小人弗克-象曰-公用亨於天子-小人害也。" tabindex="-1">九三：公用亨於天子，小人弗克 象曰：公用亨於天子，小人害也。 <a class="header-anchor" href="#九三-公用亨於天子-小人弗克-象曰-公用亨於天子-小人害也。" aria-label="Permalink to “九三：公用亨於天子，小人弗克 象曰：公用亨於天子，小人害也。”">​</a></h3><h3 id="九四-匪其彭-無咎-象曰-匪其彭-無咎-明辨晰也。" tabindex="-1">九四：匪其彭，無咎 象曰：匪其彭，無咎，明辨晰也。 <a class="header-anchor" href="#九四-匪其彭-無咎-象曰-匪其彭-無咎-明辨晰也。" aria-label="Permalink to “九四：匪其彭，無咎 象曰：匪其彭，無咎，明辨晰也。”">​</a></h3><h3 id="六五-厥孚交如-威如-吉-象曰-厥孚交如-信以發志也。威如之吉-易而無備也。" tabindex="-1">六五：厥孚交如，威如，吉 象曰：厥孚交如，信以發志也。威如之吉，易而無備也。 <a class="header-anchor" href="#六五-厥孚交如-威如-吉-象曰-厥孚交如-信以發志也。威如之吉-易而無備也。" aria-label="Permalink to “六五：厥孚交如，威如，吉 象曰：厥孚交如，信以發志也。威如之吉，易而無備也。”">​</a></h3><p>六五柔得尊位，大中而上下應之，故曰厥孚交如。言孚發於中而應之者，交至也。夫以柔德而主眾剛，推誠任物，易而無備。所可戒者，在於無威。故曰威如吉。此聖人所以儆戒人君，優遊不暴，柔而不立者也。為人君者，剛而不暴，柔而不可犯，此所以為皇極之道。</p><h3 id="上九-自天佑之-吉-無不利-象曰-大有上吉-自天佑也。" tabindex="-1">上九：自天佑之，吉，無不利 象曰：大有上吉，自天佑也。 <a class="header-anchor" href="#上九-自天佑之-吉-無不利-象曰-大有上吉-自天佑也。" aria-label="Permalink to “上九：自天佑之，吉，無不利 象曰：大有上吉，自天佑也。”">​</a></h3>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
